/* Cost period switch and provider-guided cancellation. No provider credentials are collected. */
(()=>{'use strict';
const KEY='substop.subscriptions.v1';const money=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(n);const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return []}};const monthly=s=>s.amount*(s.cycle==='yearly'?1/12:s.cycle==='weekly'?52/12:1);
const providers=[
 {name:'Netflix',match:/netflix/i,url:'https://help.netflix.com/pl/node/407',label:'Instrukcja Netflix',guide:'Anuluj plan w swoim koncie Netflix. Jeśli opłaty pobiera inny dostawca, anulowanie może wymagać kontaktu z nim.'},
 {name:'Spotify',match:/spotify/i,url:'https://support.spotify.com/pl/article/cancel-premium/',label:'Instrukcja Spotify',guide:'W sekcji Zarządzaj swoim planem wybierz Anuluj subskrypcję.'},
 {name:'ChatGPT',match:/chatgpt|openai/i,url:'https://help.openai.com/pl-pl/articles/7232927-canceling-your-chatgpt-subscription',label:'Instrukcja ChatGPT',guide:'Subskrypcję anulujesz u sprzedawcy: w ChatGPT, App Store lub Google Play — zależnie od zakupu.'}
];
const hero=document.querySelector('.hero');const heroLabel=document.querySelector('.hero-label');const amount=document.getElementById('monthly');let period='monthly';const periodBar=document.createElement('div');periodBar.className='period-bar';const heading=document.createElement('span');heading.textContent='PODSUMOWANIE WYDATKÓW';heading.className='period-caption';const actions=document.createElement('div');actions.className='period-actions';periodBar.append(heading,actions);hero.insertBefore(periodBar,heroLabel);heroLabel.style.display='none';
for(const [value,label] of [['monthly','Miesięcznie'],['yearly','Rocznie']]){const b=document.createElement('button');b.type='button';b.className='period-button';b.textContent=label;b.setAttribute('aria-pressed',String(period===value));b.onclick=()=>{period=value;updatePeriod()};actions.append(b)}
const originalSub=document.querySelector('.hero-sub');const updatePeriod=()=>{const total=read().filter(s=>s.status==='active').reduce((n,s)=>n+monthly(s),0);const display=`${new Intl.NumberFormat('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2}).format(total*(period==='yearly'?12:1))} <small>zł</small>`;if(amount.innerHTML!==display)amount.innerHTML=display;const subtitle=period==='yearly'?'Szacunkowy koszt w skali roku':'Szacunkowy koszt aktywnych subskrypcji';if(originalSub.textContent!==subtitle)originalSub.textContent=subtitle;actions.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===(period==='yearly'?'Rocznie':'Miesięcznie'))))};
const observer=new MutationObserver(()=>{if(!amount.dataset.updating){amount.dataset.updating='1';updatePeriod();delete amount.dataset.updating}});observer.observe(amount,{childList:true,subtree:true,characterData:true});
const nav=document.querySelector('.nav[data-nav="settings"]');nav.dataset.nav='cancel';nav.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10l4 4v14H3V7zM7 3v5h10V3M8 13h8m-8 4h5"/></svg>Anuluj';
const screen=document.createElement('div');screen.id='cancel';screen.className='screen';screen.innerHTML='<div class="welcome"><div class="eyebrow">ZATRZYMAJ NIEPOTRZEBNE OPŁATY</div><h1>Odzyskaj swoje <span class="gradient">pieniądze.</span></h1></div><section class="section cancel-intro"><div class="cancel-note"><b>Najpierw anuluj u dostawcy</b><p>SubStop otworzy oficjalną instrukcję lub panel rozliczeń. Samo oznaczenie subskrypcji jako anulowanej tutaj nie zatrzymuje pobierania opłat.</p></div><div class="section-head"><h2>Aktywne subskrypcje</h2></div><div id="cancel-list" class="cancel-list"></div></section><section class="section"><div class="section-head"><h2>Płatność przez sklep?</h2></div><div class="cancel-store"><a href="https://support.apple.com/pl-pl/118428" target="_blank" rel="noopener noreferrer"> Apple App Store ↗</a><a href="https://support.google.com/googleplay/answer/7018481?hl=pl" target="_blank" rel="noopener noreferrer">▶ Google Play ↗</a></div><p class="cancel-tip">Jeśli płatność pobiera Apple lub Google, anuluj ją w odpowiednim sklepie — nawet jeśli aplikacja nazywa się inaczej.</p></section>';
document.getElementById('settings').after(screen);
function node(tag,cls,text){const d=document.createElement(tag);d.className=cls;if(text!==undefined)d.textContent=text;return d}
function renderCancel(){const list=document.getElementById('cancel-list');list.replaceChildren();const active=read().filter(s=>s.status==='active');if(!active.length){list.append(node('div','cancel-empty','Nie masz aktywnych subskrypcji do anulowania.'));return}active.forEach(s=>{const p=providers.find(x=>x.match.test(s.name));const card=node('article','cancel-card');const head=node('div','cancel-row');head.append(node('b','',s.name),node('strong','',money(s.amount)));card.append(head,node('p','cancel-description',p?p.guide:'Sprawdź sposób anulowania w panelu lub na stronie pomocy operatora.'));
if(p?.name==='Netflix'){
  const steps=node('div','netflix-steps');steps.append(node('div','netflix-step','1. Otwórz bezpiecznie stronę anulowania Netflix.'),node('div','netflix-step','2. Zaloguj się wyłącznie na stronie Netflix i wybierz Potwierdź anulowanie.'),node('div','netflix-step','3. Sprawdź potwierdzenie u Netflixa, a następnie wróć tutaj.'));card.append(steps);
  const direct=node('a','provider-link netflix-direct','Otwórz anulowanie w Netflix ↗');direct.href='https://www.netflix.com/cancelplan';direct.target='_blank';direct.rel='noopener noreferrer';card.append(direct);
  const info=node('a','netflix-help','Oficjalna instrukcja Netflix ↗');info.href=p.url;info.target='_blank';info.rel='noopener noreferrer';card.append(info);
  card.append(node('p','netflix-warning','SubStop nie ma dostępu do Twojego konta Netflix. Otwarcie tej strony ani kliknięcie potwierdzenia w SubStop nie anuluje samodzielnie subskrypcji.'));
}else if(p){const a=node('a','provider-link',p.label+' ↗');a.href=p.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a)}else card.append(node('div','unknown-provider','Nie znaleziono oficjalnej instrukcji dla tej nazwy. Sprawdź dostawcę na rachunku lub w historii płatności.'));
const button=node('button','confirm-cancel','Potwierdzam anulowanie u dostawcy');button.type='button';button.onclick=()=>{if(!confirm('Czy faktycznie anulowano subskrypcję „'+s.name+'” u operatora? Sam SubStop nie anuluje płatności.'))return;const current=read(),item=current.find(x=>x.id===s.id);if(!item)return;item.status='paused';try{localStorage.setItem(KEY,JSON.stringify(current));location.reload()}catch{alert('Nie udało się zapisać zmiany')}};card.append(button);list.append(card)})}
nav.addEventListener('click',()=>{document.querySelectorAll('.screen').forEach(e=>e.classList.toggle('active',e.id==='cancel'));document.querySelectorAll('.nav').forEach(e=>e.classList.toggle('active',e===nav));renderCancel();scrollTo({top:0,behavior:'smooth'})});
document.querySelectorAll('.nav[data-nav]').forEach(b=>{if(b!==nav)b.addEventListener('click',()=>screen.classList.remove('active'))});document.getElementById('avatar').addEventListener('click',()=>screen.classList.remove('active'));
updatePeriod();renderCancel();
})();
